    intervals.append((int(data[i]), int(data[i+1])))
for i in range(2+n, 2+n+m*2, 2):
    queries.append((int(data[i]), int(data[i+1]))

for x, y in queries:
    count = 0
    for l, r in intervals:
        if l <= x and y <= r:
            count = 1
            break
    if count == 0:
        print(-1)
    else:
        print(count)

